import time
import functools

def timer(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        print(f"{func.__name__} executed in {end_time - start_time:.6f}s")
        return result
    return wrapper

# Example usage:
@timer
def compute_square(n):
    return n * n

def parse_query_string(query):
    params = query.split('&')
    parsed = {}
    for param_pair in params:
        key, value = param_pair.split('=')
        parsed[key] = value
    return parsed

result = parse_query_string('foo=1&bar=hello')
print(result)  # Output: {'foo': '1', 'bar': 'hello'}

import time

class ExecutionTimer:
    def __enter__(self):
        self.start_time = time.time()
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        elapsed = time.time() - self.start_time
        print(f'Execution took {elapsed:.2f} seconds.')
        if exc_type is not None:
            print(f'Caught error: {exc_value}')

def safe_divide(a, b):
    with ExecutionTimer():
        return a / b

# Example usage:
print(safe_divide(10, 2))   # Output: 5.00 s - 5.0
print(safe_divide(10, 0))   // Output: Execution took 0.00 seconds.
                            // Caught error: division by zero

