```python
def deep_copy(obj):
    if isinstance(obj, dict):
        return {key: deep_copy(val) for key, val in obj.items()}
    elif isinstance(obj, list):
        return [deep_copy(item) for item in obj]
    else:
        return obj

nested_dict = {'a': 1, 'b': {'c': 2}}
copied_dict = deep_copy(nested_dict)
