import time
import functools
import requests

def retry_on_connection(max_retries=3, base_delay=1):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            retries = 0
            while retries < max_retries:
                try:
                    return func(*args, **kwargs)
                except requests.ConnectionError:
                    wait = base_delay * (2 ** retries)
                    print(f"Retry {retries + 1} after waiting {wait}s.")
                    time.sleep(wait)
                    retries += 1
            raise
        return wrapper
    return decorator

# Example usage:
@retry_on_connection(max_retries=5, base_delay=2)
def fetch_url(url):
    requests.get(url)

